      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The Quinquennium Neronis</text><rect x=\"100\" y=\"200\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">54 – 59 CE</text><text x=\"550\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Nero's first five years</text><text x=\"550\" y=\"350\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">A reign of unusual good government</text><rect x=\"100\" y=\"450\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"510\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">THE TWO ADVISORS</text><text x=\"550\" y=\"560\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Seneca (philosophy)</text><text x=\"550\" y=\"600\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Burrus (the praetorian guard)</text><rect x=\"200\" y=\"720\" width=\"700\" height=\"100\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"765\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">The proof that philosophy</text><text x=\"550\" y=\"795\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">can briefly steady a throne.</text></svg>",
      "caption": "The good years"
